\documentclass{article}
\usepackage{fontspec}
\setmainfont{Noto Sans Bengali}
\begin{document}

\section*{জীববিজ্ঞান দ্বিতীয় পত্র}
\subsection*{১.১ প্রাণিজগতের ভিন্নতা}

যেসব জীব নিজ দেহে খাদ্যের সংশ্লেষণ ঘটাতে পারে না এবং খাদ্যের জন্য প্রত্যক্ষ বা পরোক্ষভাবে উদ্ভিদের উপর নির্ভরশীল তাদের প্রাণী (animals) বলে। প্রাণীর কতগুলো অনন্য বৈশিষ্ট্য রয়েছে। বৈশিষ্ট্যগুলো হলো-
\begin{enumerate}
    \item প্রাণীরা জটিল বহুকোষী (multicellular) পরভোজী জীব।
    \item প্রাণিকোষ প্রোটিন ও লিপিড নির্মিত প্লাজমা আবরণী দ্বারা পরিবৃত্ত থাকে; এদের কোষে সেন্ট্রিওল থাকে।
    \item প্রাণিদেহে রায়ুকোষ ও পেশিকোষ নামক বিশেষ দুধরনের কোষ রয়েছে যেগুলো যথাক্রমে প্রাণীর উদ্দীপনা পরিবহন ও চলনে সহায়তা করে।
    \item অধিকাংশ প্রাণীই যৌন পদ্ধতিতে প্রজনন করে যেখানে ডিপ্লয়েড দশা প্রধান; জন্ম, বৃদ্ধি, প্রজনন ও মৃত্যু এসব ধাপে প্রাণীর সুনির্দিষ্ট জীবনচক্র সম্পন্ন হয়।
\end{enumerate}

পৃথিবীর প্রাকৃতিক পরিবেশ বিভ্যান্ত প্রাণীর বিভিন্ন প্রজাতি ও ধরনকে প্রাণিবৈচিত্র্য বলে। পৃথিবীর মাটি, বায়ু ও পানিতে বসবাসকারী সকল প্রাণীর মধ্যে যে জিনগত ও প্রজাতিগত বৈচিত্র্য দেখা যায় তাকে প্রাণিবৈচিত্র্য বলে।

প্রকৃতিতে তিন ধরনের প্রাণিবৈচিত্র্য দেখা যায়, যথা-
\begin{enumerate}
    \item জিনগত বৈচিত্র্য (Genetic diversity): জিনগত ভিন্নতার কারণে যখন একই প্রজাতির সদস্যদের মধ্যে বৈচিত্র্য সৃষ্টি হয় তখন তাকে জিনগত বৈচিত্র্য বা অত্য়প্রজাতিক বৈচিত্র্য বলে। এক্ষেত্রে প্রজাতিতে রেস (race), জাত (variety) ইত্যাদির সৃষ্টি হয়। যেমন-বিশ্বের সকল মানুষ Homo sapiens প্রজাতিভুক্ত হলেও পৃথিবীর বিভিন্ন স্থানে এর Negroid, Mongoloid, Coucasoid ইত্যাদি রেস দেখা যায়। রেশম পোকা, ধান, গম, ইকুই ইত্যাদি জীবের একই প্রজাতিতে একাধিক জাত (varieties) দেখা যায়। প্রজাতিতে জিনের অ্যালিল ভিন্নতার কারণে জিনগত বৈচিত্র্য সৃষ্টি হয়। প্রজাতির দেহে কিছু জিন আছে যাদের শতাধিক ধরনের অ্যালিল থাকে। প্রজাতির একটি সদস্য ঐ জিনের কেবল একজোড়া অ্যালিল বহন করে। ফলে বৈচিত্র্য সৃষ্টি হয়। এছাড়া মিউটেশনের ফলে জিনের নতুন নতুন অ্যালিল সৃষ্টি হতে পারে। প্রাণীর জিনগত বৈচিত্র্য প্রকৃতিতে টিকে থাকা ও অভিযোজনে গুরুত্পূর্ণ ভূমিকা পালন করে। কোনো প্রজাতির প্রাণিগোষ্ঠীতে অধিক পরিমাণ জিনগত বৈচিত্র্য থাকলে তাদের মধ্যে অধিক প্রকরণ দেখা যায় যা পরিবর্তনশীল পরিবেশে টিকে থাকতে সহায়তা করে। অন্যদিকে কম জিনগত বৈচিত্র্য বিশিষ্ট প্রাণী সর্বদা হুমকিতে থাকে।

\end{document}

